'use strict'

/** @typedef {import('../types').CDSRuleContext} CDSRuleContext */

/*
 * Wrapper for ESLint's Rule creator:
 * https://eslint.org/docs/developer-guide/working-with-rules
 * - Must follow the ESLint prescribed convention for all rule exports
 * - ESLint uses 'create' function to traverse its AST nodes
 * - Since we do not work with an AST for cds models, a dummy 'Programm' node is used as an entry point
 * - More eslint-like API
 * - More convenience for error reports
 * @param {CDSRuleSpec} spec
 * @returns {RuleModule}
 */

const { SourceCode } = require('eslint')
const fs = require('fs')
const path = require('path')
const cds = require('@sap/cds')

const { globalCache } = require('./Cache')
const constants = require('../constants')
const isConfiguredFileType = require('./isConfiguredFileType')
const { getProjectRootPath, hasProjectRoots } = require('./projectRootPath')
const { CdsLintAssertionError } = require('./LintError')

const LOG = cds.debug('lint:plugin')
let filePrev = ''

const REGEX_COMMENT_START = '(/\\*|(.+)?//)(\\s?)+eslint-'
const REGEX_COMMENTS = new RegExp(`${REGEX_COMMENT_START}(enable|disable)(-next)?(-line)?(.+)?`, 'g')

/**
 * @param { {meta: Record<string, any>, create: Function} } spec
 */
module.exports = function createRule(spec) {
  let { meta, create } = spec
  meta = setMetaDefaults(meta)

  return {
    meta,
    /** @param {import('../types').CDSRuleContext} context */
    create: context => {
      // do a fast check to exclude most cases, i.e. irrelevant files
      const isRelevant =
        context.sourceCode.lines[0] === '' || // env. rules
        isConfiguredFileType(context.filename, 'FILES') // file rules
      if (!isRelevant) {
        return {}
      }

      return {
        /** @param {any} node */
        Program: node => {
          const file = context.filename
          if (file !== filePrev) {
            LOG?.(`File: ${context.filename}`)
          }
          const cdsContext = extendContext(node, context, meta)
          globalCache.set('context', cdsContext)
          const { isTest, isValidFile, doEnvironmentChecks, doRootModelChecks, showInEditor } = checkEntryCriteria(meta, cdsContext)
          switch (meta.model) {
            case 'none':
              if (doEnvironmentChecks) {
                if (isTest || !globalCache.has(`rule:${cdsContext.id}`)) {
                  LOG?.(`  Model: "${meta.model}" Rule: ${context.id}`)
                  globalCache.set(`rule:${cdsContext.id}:${globalCache.get('rootpath')}`, 'done')
                  createReport(node, cdsContext, meta, create)
                }
              }
              break

            case 'inferred':
              if (isValidFile && doRootModelChecks) {
                if (showInEditor) {
                  globalCache.remove(`model:${globalCache.get('rootpath')}`)
                  globalCache.remove(`rule:${cdsContext.id}:${globalCache.get('rootpath')}`)
                  globalCache.remove(`report:${context.filename}:${context.id}`)
                }
                if (isTest || showInEditor || !globalCache.has(`rule:${cdsContext.id}:${globalCache.get('rootpath')}`)) {
                  LOG?.(`  Model: "${meta.model}" Rule: ${context.id}`)
                  if (!showInEditor) {
                    globalCache.set(`rule:${cdsContext.id}:${globalCache.get('rootpath')}`, 'done')
                  }
                  createReport(node, cdsContext, meta, create)
                } else {
                  if (globalCache.has(`report:${context.filename}:${context.id}`)) {
                    const reports = globalCache.get(`report:${context.filename}:${context.id}`)
                    for (const r of Array.from(/** @type {any} */(reports))) {
                      context.report(JSON.parse(r))
                    }
                    globalCache.remove(`report:${context.filename}:${context.id}`)
                    globalCache.set(`rule:${cdsContext.id}:${globalCache.get('rootpath')}`, 'done')
                  }
                }
              }
              break

            default:
              if (isValidFile) {
                LOG?.(`  Model: "${meta.model}" Rule: ${context.id}`)
                createReport(node, cdsContext, meta, create)
              }
              break
          }
          filePrev = file
        }
      }
    }
  }
}

function isRunningWithCDSLint() {
  return process.argv[1].match(/cds(\.js)?$/) && process.argv[2]?.toLowerCase() === 'lint'
}

function isRunningWithESLint() {
  return process.argv[1].match(/eslint(\.js)?$/)
}

/**
 * @param {any} meta
 * @param {any} cdsContext
 */
function checkEntryCriteria(meta, cdsContext) {
  const isTest = globalCache.has('test')
  const showInEditor = cdsContext.options.includes('show')
  const isValidFile = isConfiguredFileType(cdsContext.filename, 'FILES')
  const doRootModelChecks = isTest || (hasProjectRoots() && (isRunningWithCDSLint() || isRunningWithESLint()) || showInEditor)
  // Lint all env rules independent of any parsed file (i.e. 'cds lint' uses the lintText "" API)
  const doEnvironmentChecks =
    isTest || (isRunningWithCDSLint() && cdsContext.filename === '<text>')
  return { isTest, isValidFile, doRootModelChecks, doEnvironmentChecks, showInEditor }
}

/**
 * @param {any} meta
 * @returns {{ severity: any, docs: any, model: string, [key: string]: any }}
 */
function setMetaDefaults(meta) {
  meta ??= {}
  meta.severity ??= constants.DEFAULT_RULE_SEVERITY
  meta.docs ??= {}
  meta.model ??= 'parsed'
  return meta
}

/**
 * Get report descriptors from created rules. These can take various forms,
 * from minimal return, up to fully defined ESLint report descriptors values,
 * with or without visitor keys:
 * - String is interpreted as the 'message' property
 * - Object with known CDS Visitor keys and ESLint report descriptor values
 * - Object with ESLint report descriptor keys/ values
 *
 * @param {object} node
 * @param {CDSRuleContext} cdsContext
 * @param {any} meta
 * @param {Function} create
 * @returns
 */
function createReport(node, cdsContext, meta, create) {
  const handlers = create(cdsContext)
  /**
   * TODO: Can these be rewritten to have a visitor? Note, that so far,
   * rules without a visitor cannot use eslint disable comments
   * A rule have no visitors and just return a single check:
   *  - Model Validation rules which have no well-defined CSN entry point
   *  - Environment rules
   */
  switch (typeof handlers) {
    case 'function':
      handlers()
      break

    case 'object': {
      if (meta.model !== 'none') {
        const model = cdsContext.getModel()

        if (model) {
          model.forall(/** @param {any} d */ d => {
            d = (meta.model === 'inferred') ? sanitizeFileLocation(d) : d
            const isValidLocation = (meta.model === 'parsed' && d.$location) ||
              (meta.model === 'inferred' && d.$location?.file)
            Object.entries(handlers)
              .filter(([type,]) => d.is(type) && isValidLocation)
              .forEach(([, handler]) => {
                handler(d)
              })
          })
        }
      }
      break
    }
  }
}

/** @param {any} d */
function sanitizeFileLocation(d) {
  let parent = d
  while (!parent.$location && parent.parent && !parent.parent.definitions)
    parent = d.parent
  if (parent.$location)
    d.$location = parent.$location
  return d
}

/**
 * @param {any} node
 * @param {CDSRuleContext} context
 * @param {any} meta
 */
function extendContext(node, context, meta) {
  if (!globalCache.has('test')) {
    const filePath = context.filename
    const rootPath = filePath && fs.existsSync(filePath) ? getProjectRootPath(filePath) : ''
    if (rootPath) {
      globalCache.set('rootpath', rootPath)
    }
  }

  const descriptors = Object.getOwnPropertyDescriptors(context)
  descriptors.report = {
    value: reportWrapper,
    writable: false,
    enumerable: true,
    configurable: false
  }

  const cdscontext = Object.create(Object.getPrototypeOf(context), descriptors)
  const { parserServices } = context.sourceCode || context

  cdscontext.getModel = meta.model === 'inferred'
    ? parserServices.getInferredCsn
    : parserServices.getParsedCsn

  cdscontext.getEnvironment = () => {
    const options = /** @type {any[]} */(context.options)
    return options && options[0] && options[0].environment ? options[0].environment : undefined
  }
  cdscontext.getLocation = parserServices.getLocation
  cdscontext.getNode = Object.keys(parserServices).length > 0 ? parserServices.getNode : () => node
  cdscontext.getRootPath = () => globalCache.get('rootpath')
  return cdscontext

  /** @param {any} r */
  function reportWrapper(r) {
    const line = r.loc ? r.loc.start.line : r.node.loc.start.line
    if (!isRuleDisabled(line, context)) {
      if (meta.model === 'inferred') {
        if (!r.file) {
          throw new CdsLintAssertionError(`Rule ${context.id} must return a "file" property in the rule report!`)
        }
        const file = globalCache.get('rootpath') ? resolveFilePath(r.file) : r.file
        if (cdscontext.filename === file) {
          delete r.file
          context.report(r)
        }
        if (r.file) {
          cacheReport(r, file, context, meta)
        }
      } else {
        context.report(r)
      }
    }
  }
}


/**
 * @param {number} line
 * @param {CDSRuleContext} cdsContext
 */
function isRuleDisabled(line, cdsContext) {
  let isDisabled = false
  if (cdsContext) {
    const sourcecode = cdsContext.sourceCode
    const rulesDisabled = /** @type {Record<string, string>} */(getDisabled(sourcecode.getText(), /** @type {any} */(sourcecode), line))
    const id = cdsContext.id
    isDisabled = !!(line && id in rulesDisabled && rulesDisabled[id] === 'off')
  }
  return isDisabled
}

/**
 * @param {any} r
 * @param {string} filepath
 * @param {CDSRuleContext} context
 * @param {any} meta
 */
function cacheReport(r, filepath, context, meta) {
  delete r.file
  if (r.node && r.node.range) {
    r.node.range = []
  }
  if (r.messageId) {
    r.message = meta.messages[r.messageId]
    delete r.message
  }
  if (r) {
    let reports = new Set()
    if (globalCache.has(`report:${filepath}:${context.id}`)) {
      reports = /** @type {Set<any>} */(globalCache.get(`report:${filepath}:${context.id}`))
    }
    reports.add(JSON.stringify(r))
    globalCache.set(`report:${filepath}:${context.id}`, reports)
  }
}

/**
 * @param {string} code
 * @param {any} sourcecode
 * @param {number} line
 */
function getDisabled (code, sourcecode, line) {
  /** @type {{ lineComment: number, lineDisabled: number | string, rules: Array<any>, type: string }[]} */
  const listDisabled = []
  const rules = /** @type {Record<string, any>} */(globalCache.get('rules'))
  const rulesDisabled = /** @type {Record<string, string>} */(Object.keys(rules).reduce((o, key) => ({ ...o, [key]: 'on' }), {}))
  if (code) {
    const matches = [...code.matchAll(REGEX_COMMENTS)]
    if (matches.length > 0) {
      matches.forEach(match => {
        if (match) {
          const index = match.index
          /** @type {any} */
          let matchStr = match[0]
          if (matchStr.includes('*/')) {
            matchStr = matchStr.split('*/')[0].replace('/*', '')
          } else if (matchStr.includes('//')) {
            matchStr = matchStr.split('//')[1]
          }
          if (matchStr) {
            matchStr = matchStr.trim()
          }
          ['disable', 'enable'].forEach(keyword => {
            const loc = sourcecode.getLocFromIndex(index)
            const disableType = matchStr.split(' ')[0]
            const disableRulesRaw = matchStr.split(`${disableType} `)[1]
            const disableRules = disableRulesRaw
              ? disableRulesRaw.split(',').map(/** @param {any} rule */ rule => rule.trim())
              : Object.keys(rules).map(/** @param {any} rule */ rule => `@sap/cds/${rule}`)
            /** @type {any} */
            let comment = {}
            if ([`eslint-${keyword}`, `eslint-${keyword}-line`, `eslint-${keyword}-next-line`].includes(disableType)) {
              comment = disableType.includes('-next-line')
                ? {
                  lineComment: loc.line,
                  lineDisabled: loc.line + 1,
                  rules: disableRules,
                  type: keyword
                }
                : {
                  lineComment: loc.line,
                  lineDisabled: loc.line,
                  rules: disableRules,
                  type: keyword
                }
              if (!disableType.includes('-line')) {
                comment.lineDisabled = 'EOF'
              }
            }
            listDisabled.push(comment)
          })
        }
      })
      for (const el of listDisabled.filter(
        /** @param {any} d */ d => d.lineComment < line && (d.lineDisabled === 'EOF' || d.lineDisabled === line)
      )) {
        if (el.lineDisabled === 'EOF') {
          el.lineDisabled = getLastLine(code)
        }
        if (el.rules) {
          el.rules.forEach(/** @param {any} rule */ rule => {
            if (el.type === 'disable') {
              rulesDisabled[rule] = 'off'
            } else if (el.type === 'enable') {
              rulesDisabled[rule] = 'on'
            }
          })
        }
      }
    }
  }
  return rulesDisabled
}

/**
 * @param {string} code
 */
function getLastLine(code) {
  const lines = typeof code === 'string' ? SourceCode.splitLines(code) : code
  return lines.length - 1
}

/**
 * @param {string} file
 */
function resolveFilePath(file) {
  return path.isAbsolute(file) ? file : path.join(/** @type {string} */(globalCache.get('rootpath')), file)
}
